
CREATE TABLE "products" (
  "id" NUMBER(10) NOT NULL GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" VARCHAR2(255) NOT NULL,
  "price" NUMBER(10) NOT NULL,
  "qty" NUMBER(10) NOT NULL,
  "total" NUMBER(10) NOT NULL GENERATED ALWAYS AS (price qty) VIRTUAL,
  "tax" NUMBER(10) NOT NULL GENERATED ALWAYS AS (price 0.1) STORED
);
